            ansi_codes.append(self._color.ansi_sequence(color_system))
        if self._bgcolor is not None:
            ansi_codes.append(self._bgcolor.ansi_sequence(color_system, background=True))
        if self.bold is True:
            ansi_codes.append("\033[1m")
        if self.dim is True:
            ansi_codes.append("\033[2m")
        if self.italic is True:
            ansi_codes.append("\033[3m")
        if self.underline is True:
            ansi_codes.append("\033[4m")
        if self.blink is True:
            ansi_codes.append("\033[5m")
        if self.blink2 is True:
            ansi_codes.append("\033[6m")
        if self.reverse is True:
            ansi_codes.append("\033[7m")
        if self.conceal is True:
            ansi_codes.append("\033[8m")
        if self.strike is True:
            ansi_codes.append("\033[9m")
        if ansi_codes:
            reset_code = "\033[0m"
            return f"{\033[0m}".join([f"{code}{text}{reset_code}" for code in ansi_codes])
        return text"
