        if set_bits:
            append = attrs.append
            bits = self._attributes
            for bit_no in range(0, 9):
                bit = 1 << bit_no
                if set_bits & bit:
                    append(str(1 + bit_no) if bits & bit else str(21 + bit_no))

        if attrs:
            return f"\x1b[{';'.join(attrs)}m{text or ''}\x1b[0m"
        else:
            return text"
